async function hashPassword(password){const salt=crypto.getRandomValues(new Uint8Array(16)),iterations=120000;const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations,hash:'SHA-256'},material,256);return `pbkdf2$${iterations}$${b64(salt)}$${b64(new Uint8Array(bits))}`}
async function verifyPassword(password,user){if(user?.passwordHash?.startsWith('pbkdf2$')){const [,it,salt,expected]=user.passwordHash.split('$');const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',salt:unb64(salt),iterations:Number(it),hash:'SHA-256'},material,256);return b64(new Uint8Array(bits))===expected}return user?.password===password}

function ensureToastHost(){let h=document.querySelector('#ytToastHost');if(!h){h=document.createElement('div');h.id='ytToastHost';h.className='yt-toast-host';document.body.appendChild(h)}return h}
function notify(message,type='info',duration=3200){const h=ensureToastHost(),e=document.createElement('div');e.className=`yt-toast ${type}`;const ic={success:'check',error:'alert',warning:'alert',info:'message',loading:'sync'};e.innerHTML=`<span class="yt-toast-icon">${icon(ic[type]||'message')}</span><div><b>${type==='success'?'Terminé':type==='error'?'Erreur':type==='loading'?'Traitement en cours':'Information'}</b><p>${esc(message)}</p></div>`;h.appendChild(e);requestAnimationFrame(()=>e.classList.add('show'));if(duration>0)setTimeout(()=>{e.classList.remove('show');setTimeout(()=>e.remove(),250)},duration);return()=>{e.classList.remove('show');setTimeout(()=>e.remove(),250)}}
