const normalizePhone=v=>{let p=String(v||'').trim().replace(/[\s().-]/g,'');if(p.startsWith('00'))p='+'+p.slice(2);if(!p.startsWith('+')&&/^\d{8}$/.test(p))p='+226'+p;else if(!p.startsWith('+')&&/^(226|225)\d+$/.test(p))p='+'+p;return p};
async function reserveSequenceBlock(origin){const agency=state.agencies.find(x=>x.name===origin);const prefix=String(agency?.code||origin.slice(0,3)).toUpperCase();let block=tget(`sequence-block-${prefix}`,null);if(block&&Number(block.next)<=Number(block.end))return block;if(!navigator.onLine||!state.authToken)throw new Error(`Aucun numéro ${prefix} disponible hors ligne. Connectez brièvement l’app à Internet pour réserver un nouveau bloc de numéros.`);const r=await fetch(SERVER_URL()+'/api/v2/sequences/reserve',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.authToken},body:JSON.stringify({agencyCode:prefix,count:100})});if(!r.ok)throw new Error('Impossible de réserver les numéros de colis : '+await r.text());block=await r.json();tset(`sequence-block-${prefix}`,block);return block}
async function transferCode(origin){const agency=state.agencies.find(x=>x.name===origin);const prefix=String(agency?.code||origin.slice(0,3)).toUpperCase();const block=await reserveSequenceBlock(origin);const n=Number(block.next);block.next=n+1;tset(`sequence-block-${prefix}`,block);return `${prefix}-${String(n).padStart(5,'0')}`}
