async function loadPlatformStats(showToast=false){
  if(!isPlatformAdmin()||!state.authToken)return;
  try{
    const r=await fetch(SERVER_URL()+'/api/v2/platform/stats',{headers:{'Authorization':'Bearer '+state.authToken}});
    if(!r.ok)throw new Error(await r.text());
    state.platformStats=await r.json();
    if(showToast)notify('Statistiques actualisées.','success');
  }catch(e){if(showToast)notify('Impossible d’actualiser les statistiques : '+(e?.message||e),'error',5000)}
}
const platformMoney=n=>`${new Intl.NumberFormat('fr-FR').format(Math.round(Number(n||0)))} FCFA`;
async function loadPlatformCompanyDetail(companyId=state.platformCompanyId,showToast=false){
 if(!companyId||!isPlatformAdmin()||!state.authToken)return;
 try{
  const r=await fetch(SERVER_URL()+'/api/v2/platform/companies/'+companyId,{headers:{'Authorization':'Bearer '+state.authToken}});
  if(!r.ok)throw new Error(await r.text());
  state.platformCompanyDetail=await r.json();
  if(showToast)notify('Données de la société actualisées.','success');
 }catch(e){notify('Impossible de charger la société : '+(e?.message||e),'error',5000)}
}
function platformCompanyDetailView(){
 const d=state.platformCompanyDetail,c=d?.company||state.companies.find(x=>x.id===state.platformCompanyId),st=d?.stats||{},tab=state.platformCompanyTab||'overview';
 if(!c)return shell(`<section class="panel"><button data-platform-company-back>← Sociétés</button><p>Chargement de la société…</p></section>`);
 const tabs=[['overview','Vue d’ensemble'],['users','Utilisateurs'],['revenue','Recettes'],['operations','Opérations'],['settings','Informations']];
 const tabbar=`<div class="company-detail-tabs">${tabs.map(([id,l])=>`<button data-company-tab="${id}" class="${tab===id?'active':''}">${l}</button>`).join('')}</div>`;
 let body='';
 if(!d){body='<section class="panel"><p>Chargement des informations…</p></section>'}
 else if(tab==='overview'){
  body=`<div class="platform-kpis"><div class="kpi-card"><small>Envois Courrier</small><b>${st.shipments||0}</b><span>${st.todayShipments||0} aujourd’hui · ${st.cancelledShipments||0} annulé(s)</span></div><div class="kpi-card"><small>Recettes Courrier</small><b>${platformMoney(st.sales)}</b><span>${platformMoney(st.todaySales)} aujourd’hui</span></div><div class="kpi-card"><small>Bagages</small><b>${st.baggage||0}</b><span>${platformMoney(st.baggageRevenue)} · ${st.cancelledBaggage||0} annulé(s)</span></div><div class="kpi-card"><small>Dépenses</small><b>${platformMoney(st.expenses)}</b><span>Résultat net ${platformMoney(st.net)}</span></div><div class="kpi-card"><small>Réseau</small><b>${st.users||0} comptes</b><span>${st.agencies||0} agences</span></div></div><section class="panel"><div class="panel-head"><div><h3>Agences</h3><p>${d.agencies?.length||0} point(s) opérationnel(s)</p></div></div><div class="compact-list">${(d.agencies||[]).map(a=>`<div><b>${esc(a.name||a.city||'Agence')}</b><span>${esc(a.city||'')} · ${esc(a.address||'')}</span></div>`).join('')||'<div class="empty">Aucune agence synchronisée</div>'}</div></section>`;
 }else if(tab==='users'){
  const editing=(d.users||[]).find(u=>u.id===state.platformUserEditingId)||null;
  const agencies=[...new Set((d.agencies||[]).map(a=>a.name).filter(Boolean))];
  const editForm=editing?`<form id="platformUserEditForm" class="settings-form"><h3>Modifier ${esc(editing.name)}</h3><div class="grid"><label>Nom<input name="name" value="${esc(editing.name)}" required></label><label>Identifiant<input name="username" value="${esc(editing.username)}" required></label><label>Rôle<select name="role">${['agency','admin','superuser','company_admin'].map(r=>`<option value="${r}" ${editing.role===r?'selected':''}>${roleLabel(r)}</option>`).join('')}</select></label><label>Agence<select name="agency"><option>Toutes</option>${agencies.map(a=>`<option ${editing.agency===a?'selected':''}>${esc(a)}</option>`).join('')}</select></label><label><input type="checkbox" name="active" ${editing.active?'checked':''}> Compte actif</label></div><div class="button-row"><button class="primary">Enregistrer</button><button type="button" id="cancelPlatformUserEdit">Annuler</button></div></form>`:'';
  body=`<section class="panel"><div class="panel-head"><div><h3>Comptes utilisateurs</h3><p>Le Super Super Admin peut modifier les comptes et réinitialiser un mot de passe oublié.</p></div></div><div class="user-list">${(d.users||[]).map(u=>`<div><div class="avatar">${esc((u.name||u.username).slice(0,2).toUpperCase())}</div><div><b>${esc(u.name)}</b><span>${esc(u.username)} · ${roleLabel(u.role)} · ${esc(u.agency||'Toutes')} · ${u.active?'Actif':'Désactivé'}</span></div><div class="button-row"><button data-platform-user-edit="${u.id}">Modifier</button><button data-platform-user-reset="${u.id}" data-user-name="${esc(u.name)}">Mot de passe</button></div></div>`).join('')||'<div class="empty">Aucun utilisateur</div>'}</div>${editForm}<form id="platformCompanyUserForm" class="settings-form add-user"><h3>Ajouter un utilisateur</h3><div class="grid"><label>Nom<input name="name" required></label><label>Identifiant<input name="username" required></label><label>Mot de passe initial<input type="password" name="password" required minlength="6"></label><label>Rôle<select name="role"><option value="agency">Agence</option><option value="admin">Administrateur</option><option value="superuser">Super utilisateur</option><option value="company_admin">Administrateur société</option></select></label><label>Agence<select name="agency"><option>Toutes</option>${agencies.map(a=>`<option>${esc(a)}</option>`).join('')}</select></label></div><button class="primary">Créer le compte</button></form></section>`;
 }else if(tab==='revenue'){
  body=`<div class="platform-kpis"><div class="kpi-card"><small>Recettes Courrier</small><b>${platformMoney(st.sales)}</b></div><div class="kpi-card"><small>Recettes Bagages</small><b>${platformMoney(st.baggageRevenue)}</b></div><div class="kpi-card"><small>Recettes Tickets</small><b>${platformMoney(st.ticketRevenue)}</b></div><div class="kpi-card"><small>Dépenses</small><b>${platformMoney(st.expenses)}</b></div><div class="kpi-card"><small>Résultat net</small><b>${platformMoney(st.net)}</b></div></div><section class="panel"><div class="panel-head"><div><h3>Derniers encaissements</h3><p>Jusqu’aux 100 dernières écritures de paiement synchronisées.</p></div></div><div class="compact-list">${(d.payments||[]).map(x=>`<div><b>${platformMoney(x.amount)}</b><span>${esc(x.shipmentCode||x.code||'')} · ${esc(x.method||x.paymentMethod||'Paiement')} · ${esc(x.agency||'')} · ${x.createdAt||x.at?new Date(x.createdAt||x.at).toLocaleString('fr-FR'):''}</span></div>`).join('')||'<div class="empty">Aucune écriture de paiement détaillée synchronisée.</div>'}</div></section>`;
 }else if(tab==='operations'){
  const labels={shipment:'Courrier',baggage:'Bagage',ticket:'Ticket',payment:'Encaissement',expense:'Dépense',withdrawal:'Retrait',manifest:'Bordereau',boarding:'Embarquement'},pf=state.platformOperationFilters||{};
  const ops=(d.operations||[]).filter(o=>(!pf.type||o.type===pf.type)&&(!pf.date||String(o.at||'').slice(0,10)===pf.date)&&(!pf.q||JSON.stringify(o).toLowerCase().includes(String(pf.q).toLowerCase())));
  const editing=(d.operations||[]).find(o=>`${o.type}:${o.id}`===state.platformOperationEditingKey)||null;
  const data=editing?.data||{};
  const editForm=editing&&['shipment','baggage'].includes(editing.type)?`<section class="panel platform-operation-editor"><div class="panel-head"><div><h3>Modifier ${editing.type==='shipment'?'l’envoi':'le bagage'} ${esc(editing.code||'')}</h3><p>Modification réservée au Super Admin plateforme.</p></div></div><form id="platformOperationEditForm" class="settings-form no-wizard" data-type="${editing.type}" data-id="${editing.id}"><div class="grid">${editing.type==='shipment'?`<label>Expéditeur<input name="senderName" value="${esc(data.senderName||'')}"></label><label>Téléphone expéditeur<input name="senderPhone" value="${esc(data.senderPhone||'')}"></label><label>Destinataire<input name="receiverName" value="${esc(data.receiverName||'')}"></label><label>Téléphone destinataire<input name="receiverPhone" value="${esc(data.receiverPhone||'')}"></label><label>Origine<input name="origin" value="${esc(data.origin||'')}"></label><label>Destination<input name="destination" value="${esc(data.destination||'')}"></label><label>Type<input name="type" value="${esc(data.type||'')}"></label><label>Nombre de colis<input type="number" name="parcelCount" min="1" value="${Number(data.parcelCount||1)}"></label><label>Poids kg<input type="number" name="weight" min="0" step="0.1" value="${Number(data.weight||0)}"></label><label>Valeur déclarée<input type="number" name="declaredValue" min="0" value="${Number(data.declaredValue||0)}"></label><label>Montant Courrier<input type="number" name="fee" min="0" value="${Number(data.fee||0)}"></label>`:`<label>Client<input name="passengerName" value="${esc(data.passengerName||'')}"></label><label>Téléphone<input name="phone" value="${esc(data.phone||'')}"></label><label>Destinataire<input name="receiverName" value="${esc(data.receiverName||'')}"></label><label>Téléphone destinataire<input name="receiverPhone" value="${esc(data.receiverPhone||'')}"></label><label>Origine<input name="origin" value="${esc(data.origin||'')}"></label><label>Destination<input name="destination" value="${esc(data.destination||'')}"></label><label>Nombre<input type="number" name="count" min="1" value="${Number(data.count||1)}"></label><label>Poids kg<input type="number" name="weight" min="0" step="0.1" value="${Number(data.weight||0)}"></label><label>Valeur déclarée<input type="number" name="declaredValue" min="0" value="${Number(data.declaredValue||0)}"></label><label>Montant payé<input type="number" name="paid" min="0" value="${Number(data.paid||data.amount||0)}"></label>`}</div><label>${editing.type==='shipment'?'Description':'Contenu'}<textarea name="${editing.type==='shipment'?'description':'content'}">${esc(data[editing.type==='shipment'?'description':'content']||'')}</textarea></label><div class="button-row"><button class="primary">Enregistrer</button><button type="button" id="cancelPlatformOperationEdit">Annuler</button></div></form></section>`:'';
  body=`<section class="panel"><div class="panel-head"><div><h3>Opérations de la société</h3><p>Le Super Admin peut modifier ou annuler Courrier et Bagages. Une annulation reste dans l’historique mais son montant sort des totaux.</p></div><button id="refreshCompanyDetail">Actualiser</button></div><form id="platformOperationFilter" class="platform-operation-filter no-wizard"><label>Date<input type="date" name="date" value="${esc(pf.date||'')}"></label><label>Type<select name="type"><option value="">Tous</option><option value="shipment" ${pf.type==='shipment'?'selected':''}>Courrier</option><option value="baggage" ${pf.type==='baggage'?'selected':''}>Bagages</option><option value="ticket" ${pf.type==='ticket'?'selected':''}>Tickets</option></select></label><label class="wide">Recherche<input name="q" value="${esc(pf.q||'')}" placeholder="Code, client, agence…"></label><button class="primary">Filtrer</button></form><div class="operation-ledger">${ops.map(o=>`<div class="operation-row ${o.cancelled?'cancelled-row':''}"><span class="pill">${labels[o.type]||esc(o.type)}</span><div><b>${esc(o.label||o.code||'Opération')}</b><small>${esc(o.code||'')} ${o.agency?'· '+esc(o.agency):''} ${o.status?'· '+esc(o.status):''} ${o.lockedInManifest?'<span class="manifest-lock-badge">Sur bordereau</span>':''}</small></div><strong class="${Number(o.amount)<0?'negative':''}">${o.cancelled?'<span class="cancelled-amount">Annulé</span>':Number(o.amount)?platformMoney(o.amount):''}</strong><time>${o.at?new Date(o.at).toLocaleString('fr-FR'):''}</time>${['shipment','baggage'].includes(o.type)?`<div class="operation-actions"><button data-platform-operation-edit="${o.type}:${o.id}">Modifier</button>${o.cancelled?'':`<button class="danger" data-platform-operation-cancel="${o.type}:${o.id}">Supprimer / annuler</button>`}</div>`:''}</div>`).join('')||'<div class="empty">Aucune opération synchronisée.</div>'}</div></section>${editForm}`;
 }else{
  const es=c.settings||{};
  body=`<section class="panel"><div class="panel-head"><div><h3>Informations de la société</h3><p>Vous pouvez modifier l’identité depuis cette fiche.</p></div></div><div class="company-info-grid"><div><small>Code</small><b>${esc(c.code)}</b></div><div><small>Nom</small><b>${esc(c.name)}</b></div><div><small>Téléphone</small><b>${esc(c.phone||'-')}</b></div><div><small>Statut</small><b>${c.active?'Active':'Désactivée'}</b></div><div><small>Email support</small><b>${esc(es.supportEmail||'-')}</b></div><div><small>Site web</small><b>${esc(es.website||'-')}</b></div></div><div class="button-row"><button class="primary" data-company-edit="${c.id}">Modifier les informations</button><button data-company-toggle="${c.id}" data-active="${c.active?'1':'0'}">${c.active?'Désactiver':'Activer'}</button></div></section>`;
 }
 return shell(`<section class="welcome company-detail-head"><div><button data-platform-company-back class="back-link">← Toutes les sociétés</button><span class="eyebrow">${esc(c.code)}</span><h2>${esc(c.name)}</h2><p>Administration complète de cette société.</p><div class="button-row"><button class="primary" id="enterCompanyAdmin">Ouvrir comme administrateur société</button></div></div><span class="pill ${c.active?'success':'warning'}">${c.active?'Active':'Désactivée'}</span></section>${tabbar}${body}`);
}
function platformAdmin(){
  if(state.platformCompanyId)return platformCompanyDetailView();
  const t=state.platformStats?.totals||{};
  const statsById=new Map((state.platformStats?.companies||[]).map(x=>[x.companyId,x]));
  const editing=state.companies.find(c=>c.id===state.companyEditingId)||null;
  const es=editing?.settings||{};
  const kpis=`<div class="platform-kpis">
    <div class="kpi-card"><small>Sociétés actives</small><b>${t.activeCompanies??state.companies.filter(c=>c.active).length}</b><span>${t.companies??state.companies.length} au total</span></div>
    <div class="kpi-card"><small>Envois</small><b>${new Intl.NumberFormat('fr-FR').format(t.shipments||0)}</b><span>${new Intl.NumberFormat('fr-FR').format(t.todayShipments||0)} aujourd’hui</span></div>
    <div class="kpi-card"><small>Recettes Courrier</small><b>${platformMoney(t.sales)}</b><span>${platformMoney(t.todaySales)} aujourd’hui</span></div>
    <div class="kpi-card"><small>Dépenses</small><b>${platformMoney(t.expenses)}</b><span>Solde net ${platformMoney(t.net)}</span></div>
    <div class="kpi-card"><small>Recettes Bagages</small><b>${platformMoney(t.baggageRevenue)}</b><span>${t.baggage||0} bagage(s) · ${t.users||0} utilisateurs</span></div>
  </div>`;
  const companies=state.companies.map(c=>{const x=statsById.get(c.id)||{};return `<article class="company-admin-card ${c.active?'':'inactive'}">
    <div class="company-admin-head"><div class="avatar">${esc(c.code.slice(0,2))}</div><div><b>${esc(c.name)}</b><span>${esc(c.code)} · ${esc(c.phone||'Aucun téléphone')}</span></div><span class="pill ${c.active?'success':'warning'}">${c.active?'Active':'Désactivée'}</span></div>
    <div class="company-mini-stats"><span><b>${x.shipments||0}</b> envois</span><span><b>${platformMoney(x.sales)}</b> courrier</span><span><b>${platformMoney(x.expenses)}</b> dépenses</span><span><b>${platformMoney(x.net)}</b> net</span><span><b>${x.users||0}</b> comptes</span><span><b>${x.agencies||0}</b> agences</span></div>
    <div class="company-actions"><button class="primary" data-company-open="${c.id}">Ouvrir</button><button data-company-edit="${c.id}">Modifier</button><button data-company-toggle="${c.id}" data-active="${c.active?'1':'0'}">${c.active?'Désactiver':'Activer'}</button><button class="danger" data-company-delete="${c.id}" data-code="${esc(c.code)}" data-name="${esc(c.name)}">Supprimer</button></div>
  </article>`}).join('')||'<div class="empty">Aucune société</div>';
  const formTitle=editing?'Modifier la société':'Ajouter une société';
  const formIntro=editing?`Mettez à jour l’identité, le logo et la charte de ${esc(editing.name)}.`:'Créez son espace isolé et son premier administrateur.';
  return shell(`<section class="welcome"><div><span class="eyebrow">Plateforme multi-sociétés</span><h2>Super Super Admin</h2><p>Administration des sociétés, activité commerciale, utilisateurs et exploitation globale.</p></div><button id="refreshPlatformStats">Actualiser</button></section>${kpis}<section class="panel"><div class="panel-head"><div><h3>Sociétés</h3><p>${state.companies.length} société(s) enregistrée(s)</p></div></div><div class="company-admin-list">${companies}</div></section><section class="panel"><form id="companyForm" class="settings-form add-user" data-mode="${editing?'edit':'create'}" data-company-id="${editing?.id||''}"><h3>${formTitle}</h3><p>${formIntro}</p><div class="grid"><label>Code société<input name="code" required maxlength="40" placeholder="EX. TRANSFASO" value="${esc(editing?.code||'')}" ${editing?'readonly':''}></label><label>Nom société<input name="name" required value="${esc(editing?.name||'')}"></label><label>Téléphone<input name="phone" value="${esc(editing?.phone||'')}"></label><label>Logo de la société<input id="companyLogoFile" type="file" accept="image/png,image/jpeg,image/webp" ${editing?'':'required'}><small>${editing?'Laissez vide pour conserver le logo actuel.':'PNG, JPG ou WebP. Le logo sera envoyé au serveur.'}</small></label><label>Couleur principale<input name="primaryColor" type="color" value="${esc(es.primaryColor||'#075f4e')}"></label><label>Couleur secondaire<input name="secondaryColor" type="color" value="${esc(es.secondaryColor||'#063d34')}"></label><label>Couleur accent<input name="accentColor" type="color" value="${esc(es.accentColor||'#1769df')}"></label><label>Titre suivi<input name="trackingTitle" value="${esc(es.trackingTitle||'Suivez votre envoi')}"></label><label>Sous-titre suivi<input name="trackingSubtitle" value="${esc(es.trackingSubtitle||'Du dépôt jusqu’au point de retrait, étape par étape.')}"></label><label>Email support<input name="supportEmail" type="email" value="${esc(es.supportEmail||'')}"></label><label>Site web<input name="website" type="url" value="${esc(es.website||'')}"></label>${editing?'':`<label>Nom administrateur<input name="adminName" value="Administrateur" required></label><label>Identifiant admin<input name="adminUsername" value="admin" required></label><label>Mot de passe initial<input name="adminPassword" type="password" required></label>`}</div><div id="companyLogoPreview" class="company-logo-preview">${editing?.hasLogo?'<span>Logo actuel enregistré. Choisissez un fichier uniquement pour le remplacer.</span>':''}</div><div class="button-row"><button class="primary">${editing?'Enregistrer les modifications':'Créer la société'}</button>${editing?'<button type="button" id="cancelCompanyEdit">Annuler</button>':''}</div></form></section>`)
}
function admin(){if(!canManageUsers())return dashboard();if(isPlatformAdmin())return platformAdmin();if(!isSuper())return adminTeamSettings();return shell(`<div class="admin-grid"><section class="panel"><div class="panel-head"><div><h3>Identité et tickets</h3><p>Personnalisation de l’en-tête d’impression</p></div></div><form id="brandForm" class="settings-form"><label>Nom de la société<input name="companyName" value="${esc(state.settings.companyName)}"></label><div class="grid"><label>Téléphone<input name="phone" value="${esc(state.settings.phone)}"></label><label>Adresse / trajet<input name="address" value="${esc(state.settings.address)}"></label></div><label>Logo de l’entreprise<input type="file" id="logoFile" accept="image/*"></label>${state.settings.logo?`<img src="${state.settings.logo}" class="logo-preview">`:''}<div class="brand-theme-grid"><label>Couleur principale<input type="color" name="primaryColor" value="${esc(state.settings.primaryColor||'#075f4e')}"></label><label>Couleur secondaire<input type="color" name="secondaryColor" value="${esc(state.settings.secondaryColor||'#063d34')}"></label><label>Couleur accent<input type="color" name="accentColor" value="${esc(state.settings.accentColor||'#1769df')}"></label></div><label>Titre page suivi<input name="trackingTitle" value="${esc(state.settings.trackingTitle||'Suivez votre envoi')}"></label><label>Sous-titre page suivi<textarea name="trackingSubtitle">${esc(state.settings.trackingSubtitle||'Du dépôt jusqu’au point de retrait, étape par étape.')}</textarea></label><div class="grid"><label>Email support<input type="email" name="supportEmail" value="${esc(state.settings.supportEmail||'')}"></label><label>Site web<input type="url" name="website" value="${esc(state.settings.website||'')}"></label></div><label>Image de couverture suivi (URL)<input type="url" name="heroImageUrl" value="${esc(state.settings.heroImageUrl||'')}"></label><div class="brand-live-preview" style="--preview-primary:${esc(state.settings.primaryColor||'#075f4e')};--preview-secondary:${esc(state.settings.secondaryColor||'#063d34')}"><b>Aperçu de la charte</b><span>Ces couleurs seront appliquées à l’app et au suivi client.</span></div><button class="primary">Enregistrer l’identité et la charte</button></form></section><section class="panel"><div class="panel-head"><div><h3>Tarification</h3><p>Règles appliquées par défaut</p></div></div><form id="pricingForm" class="settings-form"><label>Pourcentage sur la valeur du colis<input type="number" min="0" step="0.1" name="parcelRate" value="${state.settings.parcelRate}"></label><label>Tarif fixe enveloppe<input type="number" min="0" name="envelopeFee" value="${state.settings.envelopeFee}"></label><button class="primary">Mettre à jour les tarifs</button></form></section><section class="panel full"><div class="panel-head"><div><h3>Configuration SMS IKODDI</h3><p>Les clés sont configurées depuis le compte administrateur</p></div><span class="pill ${state.settings.smsEnabled?'success':'warning'}">${state.settings.smsEnabled?'Activé':'Désactivé'}</span></div><form id="smsForm" class="settings-form"><div class="grid"><label>URL API<input name="ikoddiBaseUrl" value="${esc(state.settings.ikoddiBaseUrl)}"></label><label>Organization / Group ID<input name="ikoddiGroupId" value="${esc(state.settings.ikoddiGroupId)}"></label><label>Clé API<input type="password" name="ikoddiApiKey" value="${esc(state.settings.ikoddiApiKey)}"></label><label>Sender ID<input name="ikoddiSenderId" maxlength="11" value="${esc(state.settings.ikoddiSenderId)}"></label></div><div class="checks"><label><input type="checkbox" name="smsEnabled" ${state.settings.smsEnabled?'checked':''}> Activer les SMS</label><label><input type="checkbox" name="smsOnCreate" ${state.settings.smsOnCreate?'checked':''}> Au dépôt</label><label><input type="checkbox" name="smsOnArrival" ${state.settings.smsOnArrival?'checked':''}> À l’arrivée</label><label><input type="checkbox" name="smsOnDelivery" ${state.settings.smsOnDelivery?'checked':''}> À la livraison</label></div><button class="primary">Enregistrer IKODDI</button></form><div class="security-note">Pour une mise en production, la clé IKODDI doit idéalement être conservée sur un serveur sécurisé plutôt que directement dans l’APK.</div></section><section class="panel"><div class="panel-head"><div><h3>Impression</h3><p>Format et connexion imprimante</p></div></div><form id="printerForm" class="settings-form"><div class="grid"><label>Largeur papier<select name="printWidth"><option value="80" ${currentPrinter().printWidth==='80'?'selected':''}>80 mm</option><option value="58" ${currentPrinter().printWidth==='58'?'selected':''}>58 mm</option></select></label><label>Hauteur ticket<select name="printHeight"><option value="80" ${currentPrinter().printHeight==='80'?'selected':''}>80 mm</option><option value="57" ${currentPrinter().printHeight==='57'?'selected':''}>57 mm</option></select></label><label>Mode de connexion<select name="printerMode" id="printerMode"><option value="android" ${currentPrinter().printerMode==='android'?'selected':''}>Service d’impression Android</option><option value="usb" ${currentPrinter().printerMode==='usb'?'selected':''}>Imprimante USB / OTG</option><option value="bluetooth" ${currentPrinter().printerMode==='bluetooth'?'selected':''}>Bluetooth ESC/POS direct</option><option value="integrated" ${currentPrinter().printerMode==='integrated'?'selected':''}>Imprimante intégrée au POS</option></select></label><label><input type="checkbox" name="autoPrint" ${currentPrinter().autoPrint?'checked':''}> Imprimer automatiquement après enregistrement</label></div><div class="grid"><label>Imprimante Bluetooth associée<select name="bluetoothAddress" id="bluetoothPrinterSelect"><option value="${esc(currentPrinter().bluetoothAddress||'')}">${currentPrinter().bluetoothName?esc(currentPrinter().bluetoothName):'Choisir après détection'}</option></select></label><label>Nom mémorisé<input name="bluetoothName" id="bluetoothPrinterName" value="${esc(currentPrinter().bluetoothName||'')}" readonly></label></div><div class="button-row"><button class="primary">Enregistrer</button><button type="button" id="detectBluetoothPrinters">Détecter les imprimantes</button><button type="button" id="testBluetoothPrinter">Ticket test Bluetooth</button><button type="button" id="openPrintSettings">Paramètres d’impression</button><button type="button" id="openBluetoothSettings">Associer en Bluetooth</button><button type="button" id="requestCameraPermission" class="accent-action">Autoriser la caméra</button><button type="button" id="openAppPermissions">Paramètres de l’application</button></div><p class="security-note">Pour une imprimante portable générique, associez-la d’abord dans Android, puis cliquez sur « Détecter les imprimantes ». Le mode Bluetooth utilise directement le protocole ESC/POS.</p></form></section><section class="panel full"><div class="panel-head"><div><h3>Mentions spéciales</h3><p>Textes personnalisés imprimés selon le service.</p></div></div><form id="mentionsForm" class="settings-form"><div class="grid"><label>Courrier<textarea name="specialMentionCourier">${esc(state.settings.specialMentionCourier||'')}</textarea></label><label>Bagages / colis<textarea name="specialMentionBaggage">${esc(state.settings.specialMentionBaggage||'')}</textarea></label><label>Ticket / reçu<textarea name="specialMentionTicket">${esc(state.settings.specialMentionTicket||'')}</textarea></label></div><button class="primary">Enregistrer les mentions</button></form></section><section class="panel"><div class="panel-head"><div><h3>Annuaire public</h3><p>QR du reçu client</p></div></div><form id="directoryForm" class="settings-form"><label>URL publique de suivi client<input name="trackingBaseUrl" value="${esc(state.settings.trackingBaseUrl||'')}" placeholder="https://suivi.yam-trans.com"></label><label>URL publique des agences<input name="agencyDirectoryUrl" value="${esc(state.settings.agencyDirectoryUrl)}" placeholder="https://yamtrans.com/agences"></label><p class="security-note">Le QR du reçu ouvre cette page afin que le client choisisse une agence et l’affiche sur Google Maps.</p><button class="primary">Enregistrer l’URL</button></form></section><section class="panel full"><div class="panel-head"><div><h3>Villes et agences</h3><p>Une ville peut contenir une ou plusieurs agences</p></div></div><div class="user-list">${state.agencies.map(a=>`<div><div class="avatar">${esc(a.code)}</div><div><b>${esc(a.name)}</b><span>${esc(a.city)} · ${esc(a.address)}${a.pickupName?' · '+esc(a.pickupName):''}</span>${agencyMapLink(a)?`<a class="map-mini-link" href="${esc(agencyMapLink(a))}" target="_blank" rel="noopener">${icon('pin')} Voir sur Google Maps</a>`:''}</div><button data-delete-agency="${a.id}">Supprimer</button></div>`).join('')}</div><form id="agencyForm" class="settings-form add-user"><h4>Nouvelle agence</h4><div class="grid"><label>Nom de l’agence<input name="name" required></label><label>Ville<input name="city" required></label><label>Code destination (3 lettres)<input name="code" maxlength="3" required placeholder="OUA"></label><label>Adresse<input name="address" required placeholder="Quartier, rue, repère"></label><label>Nom du point de retrait<input name="pickupName" required placeholder="Ex. Agence Yam-Trans Gounghin"></label><label>Indication pour trouver l’agence<textarea name="pickupDirections" required placeholder="Ex. En face de..., portail vert, à côté de..."></textarea></label><label>Lien Google Maps<input name="mapsUrl" type="url" placeholder="https://maps.google.com/..."></label><label>Latitude<input name="latitude" inputmode="decimal"></label><label>Longitude<input name="longitude" inputmode="decimal"></label></div><p class="security-note">Le lien Google Maps est affiché au client sur le suivi, avec le nom et l’indication du point de retrait.</p><button class="primary">Créer l’agence</button></form></section><section class="panel full"><div class="panel-head"><div><h3>Comptes et agences</h3><p>Créer les utilisateurs, leurs rôles et leur agence</p></div></div><div class="user-list">${state.users.map(u=>`<div><div class="avatar">${esc(u.name.slice(0,2).toUpperCase())}</div><div><b>${esc(u.name)}</b><span>${esc(u.username)} · ${roleLabel(u.role)}${u.role==='agency'?` · Agence ${esc(u.agency)}`:''}</span></div>${u.id!=='admin'?`<button data-delete-user="${u.id}">Supprimer</button>`:''}</div>`).join('')}</div><form id="userForm" class="settings-form add-user"><h4>Nouveau compte</h4><div class="grid"><label>Nom<input name="name" required></label><label>Identifiant<input name="username" required></label><label>Mot de passe<input name="password" required></label><label>Rôle<select name="role"><option value="agency">Rôle agence</option><option value="admin">Administrateur</option><option value="superuser">Super utilisateur</option></select></label><label>Agence<select name="agency">${agencyOptions()}<option>Toutes</option></select></label></div><button class="primary">Créer le compte</button></form></section><section class="panel full"><div class="panel-head"><div><h3>Synchronisation serveur</h3><p>Connecte les données de toutes les agences lorsque Internet est disponible.</p></div><span class="pill ${state.settings.syncEnabled?'success':'warning'}">${state.settings.syncEnabled?'Activée':'Désactivée'}</span></div><form id="syncForm" class="settings-form"><div class="grid"><label>Serveur central<input name="syncBaseUrl" value="${esc(state.settings.syncBaseUrl||SERVER_URL())}" placeholder="https://api.votredomaine.com"></label><label><input type="checkbox" name="syncEnabled" ${state.settings.syncEnabled?'checked':''}> Activer la synchronisation</label><label><input type="checkbox" name="syncAuto" ${state.settings.syncAuto?'checked':''}> Synchroniser automatiquement</label></div><div class="button-row"><button class="primary">Enregistrer</button><button type="button" id="syncNowButton">Synchroniser maintenant</button></div><p class="security-note">Dernière synchronisation : ${state.settings.lastSyncAt?new Date(state.settings.lastSyncAt).toLocaleString('fr-FR'):'Jamais'}</p></form></section><section class="panel full"><div class="panel-head"><div><h3>Sécurité, sauvegarde et audit</h3><p>Traçabilité des actions, sauvegarde locale et règles antifraude.</p></div></div><form id="securityForm" class="settings-form"><div class="grid"><label>Conservation des photos (jours)<input type="number" name="photoRetentionDays" min="1" value="${state.settings.photoRetentionDays||14}"></label><label>Copies reçu client<input type="number" name="receiptCopies" min="1" max="5" value="${state.settings.receiptCopies||1}"></label><label>Copies étiquette<input type="number" name="labelCopies" min="1" max="5" value="${state.settings.labelCopies||1}"></label><label><input type="checkbox" name="allowReprint" ${state.settings.allowReprint?'checked':''}> Autoriser la réimpression journalisée</label><label><input type="checkbox" name="requireManagerCancellation" ${state.settings.requireManagerCancellation?'checked':''}> Validation responsable pour annulation</label></div><div class="button-row"><button class="primary">Enregistrer la sécurité</button><button type="button" id="exportBackup">Exporter une sauvegarde</button><label class="file-button">Restaurer<input type="file" id="importBackup" accept="application/json"></label></div></form><div class="audit-list">${state.audit.slice(0,30).map(a=>`<div><b>${esc(a.action)}</b><span>${new Date(a.at).toLocaleString('fr-FR')} · ${esc(a.user)} · ${esc(a.agency)} ${a.details?'· '+esc(a.details):''}</span></div>`).join('')||'<p>Aucune action journalisée.</p>'}</div></section></div>`)}

function captureFormDrafts(){
 const drafts={};
 document.querySelectorAll('#app form').forEach((form,idx)=>{
  const key=form.id||`form-${state.page}-${idx}`;
  const values={};
  form.querySelectorAll('input[name],select[name],textarea[name]').forEach(el=>{
   if(el.type==='file')return;
   values[el.name]={value:el.value,checked:el.checked,type:el.type};
  });
  drafts[key]=values;
 });
 const active=document.activeElement;
 return {drafts,focus:active?.name||'',formId:active?.form?.id||'',selectionStart:typeof active?.selectionStart==='number'?active.selectionStart:null};
}
function restoreFormDrafts(snapshot){
 if(!snapshot?.drafts)return;
 Object.entries(snapshot.drafts).forEach(([key,values])=>{
  const form=document.getElementById(key)||[...document.querySelectorAll('#app form')].find((f,idx)=>`form-${state.page}-${idx}`===key);
  if(!form)return;
  Object.entries(values).forEach(([name,data])=>{
   const el=form.elements?.namedItem(name);if(!el||el instanceof RadioNodeList)return;
   if(data.type==='checkbox'||data.type==='radio')el.checked=Boolean(data.checked);else el.value=data.value;
  });
 });
 if(snapshot.focus){const form=snapshot.formId?document.getElementById(snapshot.formId):null;const el=form?.elements?.namedItem(snapshot.focus)||document.querySelector(`[name="${CSS.escape(snapshot.focus)}"]`);if(el&&typeof el.focus==='function'){el.focus();if(snapshot.selectionStart!=null&&typeof el.setSelectionRange==='function'){try{el.setSelectionRange(snapshot.selectionStart,snapshot.selectionStart)}catch{}}}}
}
const SETTINGS_CATEGORIES=[
 ['users','Utilisateurs','Comptes, rôles et accès','users'],
 ['printer','Imprimante','Bluetooth, format et tests','printer'],
 ['agencies','Agences & villes','Points de retrait et localisation','pin'],
 ['pricing','Tarification','Tarifs colis et enveloppes','money'],
 ['identity','Société & identité','Logo, couleurs et informations','building'],
 ['tracking','Suivi & tickets','QR, mentions et page publique','link'],
 ['sms','Notifications SMS','Configuration IKODDI','message'],
 ['sync','Synchronisation','Offline / online et serveur','sync'],
 ['security','Sécurité & sauvegarde','Audit, sauvegarde et règles','shield']
];
function settingsCategoryForPanel(panel){
 const title=(panel.querySelector('h3')?.textContent||'').toLowerCase();
 if(title.includes('utilisateur')||title.includes('comptes et agences'))return 'users';
 if(title.includes('impression')||title.includes('imprimante'))return 'printer';
 if(title.includes('villes et agences')||title==='agences')return 'agencies';
 if(title.includes('tarification'))return 'pricing';
 if(title.includes('identité'))return 'identity';
 if(title.includes('annuaire')||title.includes('mentions'))return 'tracking';
 if(title.includes('sms'))return 'sms';
 if(title.includes('synchronisation'))return 'sync';
 if(title.includes('sécurité'))return 'security';
 return 'other';
}
function enhanceSettingsNavigation(){
 if(state.page!=='admin'||isPlatformAdmin())return;
 const main=document.querySelector('.workspace main');
 const grid=main?.querySelector('.admin-grid');
 if(!main||!grid)return;
 const allowed=isSuper()?SETTINGS_CATEGORIES:SETTINGS_CATEGORIES.filter(x=>['users','agencies'].includes(x[0]));
 const current=state.settingsSection;
 const hub=document.createElement('section');
 hub.className='settings-hub panel';
 hub.innerHTML=current?`<div class="settings-section-head"><button type="button" id="settingsBack" class="settings-back">${icon('back')} Paramètres</button><div><span class="eyebrow">PARAMÈTRES</span><h2>${esc(allowed.find(x=>x[0]===current)?.[1]||'Rubrique')}</h2></div></div>`:`<div class="panel-head"><div><span class="eyebrow">PARAMÈTRES</span><h2>Choisissez une rubrique</h2><p>Accédez directement au réglage souhaité sans parcourir une longue page.</p></div></div><div class="settings-menu-grid">${allowed.map(([id,label,desc,ico])=>`<button type="button" class="settings-menu-card" data-settings-section="${id}"><span class="settings-card-icon">${icon(ico)}</span><div><b>${label}</b><small>${desc}</small></div><i>${icon('arrowRight')}</i></button>`).join('')}</div>`;
 main.insertBefore(hub,grid);
 const panels=[...grid.querySelectorAll(':scope > .panel')];
 panels.forEach(panel=>{const cat=settingsCategoryForPanel(panel);panel.dataset.settingsCategory=cat;panel.hidden=!current||cat!==current});
 if(!current)grid.classList.add('settings-grid-hidden');else grid.classList.remove('settings-grid-hidden');
 hub.querySelectorAll('[data-settings-section]').forEach(b=>b.onclick=()=>{state.settingsSection=b.dataset.settingsSection;render()});
 hub.querySelector('#settingsBack')?.addEventListener('click',()=>{state.settingsSection='';render()});
}
const WIZARD_TITLES={
 shipmentForm:['Clients','Envoi & trajet','Paiement & validation'],
 withdrawForm:['Paiement','Identité du retrait','Confirmation'],
 manifestForm:['Voyage','Colis du bordereau','Validation'],
 agencyForm:['Agence','Localisation','Point de retrait'],
 userForm:['Identité','Rôle & agence','Confirmation'],
 brandForm:['Identité','Charte graphique','Contact & suivi'],
 smsForm:['Connexion IKODDI','Déclencheurs','Validation'],
 printerForm:['Format','Connexion','Options'],
 securityForm:['Conservation','Impression & contrôle','Sauvegarde'],
 companyCreateForm:['Société','Identité visuelle','Administrateur'],
 expenseForm:['Dépense','Affectation','Validation'],
 accountingExpenseForm:['Dépense','Affectation','Validation']
};
function validateWizardStep(form,step){
 const visible=[...form.querySelectorAll(`[data-wizard-step="${step}"] input,[data-wizard-step="${step}"] select,[data-wizard-step="${step}"] textarea`)];
 for(const el of visible){if(!el.checkValidity()){el.reportValidity();el.focus();return false}}return true;
}
function enhanceFormWizard(form){
 if(!form||form.dataset.wizardReady==='1')return;
 const skip=['loginForm','reportFilter','accountingFilter','withdrawSearchForm','shipmentForm','baggageForm','dashboardFilterForm','shipmentListFilter','companyUserEditForm','platformOperationFilter','platformOperationEditForm'];
 if(skip.includes(form.id))return;
 let stepUnits=[];
 const sections=[...form.querySelectorAll(':scope > .form-section')];
 const stepTitles=[...form.querySelectorAll(':scope > .step-title')];
 if(sections.length>=2){
  stepUnits=sections.map((section,i)=>({nodes:[section,...(stepTitles[i]?[stepTitles[i]]:[])],title:stepTitles[i]?.querySelector('h3')?.textContent||`Étape ${i+1}`}));
 }else{
  const labels=[...form.querySelectorAll('label')].filter(l=>!l.closest('.wizard-controls'));
  if(labels.length<5)return;
  const desired=Math.min(3,Math.max(2,Math.ceil(labels.length/4)));
  const size=Math.ceil(labels.length/desired);
  for(let i=0;i<labels.length;i+=size)stepUnits.push({nodes:labels.slice(i,i+size),title:(WIZARD_TITLES[form.id]||[])[stepUnits.length]||`Étape ${stepUnits.length+1}`});
 }
 if(stepUnits.length<2)return;
 form.dataset.wizardReady='1';
 const total=stepUnits.length;
 let current=Math.min(Number(state.formSteps[form.id]||0),total-1);
 stepUnits.forEach((u,idx)=>u.nodes.forEach(n=>{n.dataset.wizardStep=String(idx)}));
 const progress=document.createElement('div');progress.className='wizard-progress';form.insertBefore(progress,form.firstChild);
 const controls=document.createElement('div');controls.className='wizard-controls';controls.innerHTML=`<button type="button" class="wizard-prev">← Précédent</button><div class="wizard-count"></div><button type="button" class="wizard-next primary">Suivant →</button>`;
 const submit=[...form.querySelectorAll('button[type="submit"],button:not([type])')].find(b=>b.closest('form')===form&&b.classList.contains('primary'))||form.querySelector('button[type="submit"]');
 if(submit)form.insertBefore(controls,submit);else form.appendChild(controls);
 const paint=()=>{
  state.formSteps[form.id]=current;
  stepUnits.forEach((u,idx)=>u.nodes.forEach(n=>n.hidden=idx!==current));
  progress.innerHTML=`<div class="wizard-step-label"><span>Étape ${current+1} sur ${total}</span><b>${esc(stepUnits[current].title)}</b></div><div class="wizard-bar"><i style="width:${((current+1)/total)*100}%"></i></div>`;
  controls.querySelector('.wizard-prev').disabled=current===0;
  controls.querySelector('.wizard-next').hidden=current===total-1;
  controls.querySelector('.wizard-count').textContent=`${current+1}/${total}`;
  if(submit)submit.hidden=current!==total-1;
  form.scrollIntoView({behavior:'smooth',block:'start'});
 };
 controls.querySelector('.wizard-prev').onclick=()=>{if(current>0){current--;paint()}};
 controls.querySelector('.wizard-next').onclick=()=>{if(validateWizardStep(form,current)&&current<total-1){current++;paint()}};
 paint();
}
function enhanceAllForms(){document.querySelectorAll('#app form').forEach(enhanceFormWizard)}
function resetOperationForm(form,message='Opération enregistrée avec succès.'){
 if(!form)return;
 const id=form.id||'';
 try{form.reset()}catch{}
 if(id)delete state.formSteps[id];
 if(form.dataset)delete form.dataset.savedShipmentId;
 form.querySelectorAll('input[type="file"]').forEach(x=>{x.value='';delete x.dataset.dataUrl});
 notify(message,'success');
}

