 const select=wrap.querySelector('#companyUserEditSelect');
 if(select)select.onchange=e=>{state.companyUserEditingId=e.target.value||null;render()};
 wrap.querySelector('#cancelCompanyUserEdit')?.addEventListener('click',()=>{state.companyUserEditingId=null;render()});
