 document.querySelector('#enterCompanyAdmin')?.addEventListener('click',async e=>{try{sessionStorage.setItem('yamtransPlatformSession',JSON.stringify({token:state.authToken,user:state.user,company:state.company,companies:state.companies}));const r=await fetch(SERVER_URL()+`/api/v2/platform/companies/${state.platformCompanyId}/impersonate`,{method:'POST',headers:{'Authorization':'Bearer '+state.authToken}});if(!r.ok)throw new Error(await r.text());const d=await r.json();state.authToken=d.token;state.user=d.user;store.set('authToken',d.token);store.set('currentUser',d.user);loadTenantState(d.company,d.users||[]);state.platformCompanyId=null;state.platformCompanyDetail=null;selectInitialModule();await syncNow(true);notify(`Mode administration : ${d.company.name}`,'success');render()}catch(err){notify('Impossible d’ouvrir la société : '+(err?.message||err),'error',5000)}});
