 document.querySelector('#cancelPlatformUserEdit')?.addEventListener('click',()=>{state.platformUserEditingId=null;render()});
 document.querySelectorAll('[data-platform-user-reset]').forEach(b=>b.onclick=async()=>{const pwd=prompt(`Nouveau mot de passe pour ${b.dataset.userName} :`);if(!pwd)return;if(pwd.length<6){notify('Le mot de passe doit contenir au moins 6 caractères.','warning');return}if(!confirm('Confirmer la réinitialisation du mot de passe ?'))return;try{const r=await fetch(SERVER_URL()+`/api/v2/platform/companies/${state.platformCompanyId}/users/${b.dataset.platformUserReset}`,{method:'PUT',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.authToken},body:JSON.stringify({newPassword:pwd})});if(!r.ok)throw new Error(await r.text());notify('Mot de passe réinitialisé.','success')}catch(e){notify('Réinitialisation impossible : '+(e?.message||e),'error',5000)}});
 const edit=document.querySelector('#platformUserEditForm');if(edit)edit.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(edit));d.active=edit.elements.active.checked;d.modules={courier:edit.elements.moduleCourier?.checked!==false,baggage:edit.elements.moduleBaggage?.checked!==false,tickets:!!edit.elements.moduleTickets?.checked,ticketRoles:[...edit.querySelectorAll('[name="ticketRoles"]:checked')].map(x=>x.value)};try{const r=await fetch(SERVER_URL()+`/api/v2/platform/companies/${state.platformCompanyId}/users/${state.platformUserEditingId}`,{method:'PUT',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.authToken},body:JSON.stringify(d)});if(!r.ok)throw new Error(await r.text());state.platformUserEditingId=null;await loadPlatformCompanyDetail();notify('Utilisateur modifié.','success');render()}catch(err){notify('Modification impossible : '+(err?.message||err),'error',5000)}};
 const create=document.querySelector('#platformCompanyUserForm');if(create)create.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(create));d.modules={courier:create.elements.moduleCourier?.checked!==false,baggage:create.elements.moduleBaggage?.checked!==false,tickets:!!create.elements.moduleTickets?.checked,ticketRoles:[...create.querySelectorAll('[name="ticketRoles"]:checked')].map(x=>x.value)};d.companyCode=state.platformCompanyDetail?.company?.code||'';try{const r=await fetch(SERVER_URL()+'/api/v2/admin/users',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.authToken},body:JSON.stringify(d)});if(!r.ok)throw new Error(await r.text());resetOperationForm(create,'Compte créé.');await loadPlatformCompanyDetail();render()}catch(err){notify('Création du compte impossible : '+(err?.message||err),'error',5000)}};
