 document.querySelectorAll('[data-platform-operation-cancel]').forEach(b=>b.onclick=async()=>{const [type,id]=b.dataset.platformOperationCancel.split(':'),op=(state.platformCompanyDetail?.operations||[]).find(x=>x.type===type&&x.id===id),reason=prompt('Motif de l’annulation / suppression :','Correction administrative')||'';const lockNote=op?.lockedInManifest?'\n\nAttention : cet envoi est déjà sur un bordereau. Seul votre compte Super Admin plateforme est autorisé à l’annuler.':'';if(!confirm('Confirmer ? L’opération restera visible avec la mention « Annulé » et son montant ne sera plus comptabilisé.'+lockNote))return;try{const r=await fetch(SERVER_URL()+`/api/v2/platform/companies/${state.platformCompanyId}/operations/${type}/${id}`,{method:'PUT',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.authToken},body:JSON.stringify({action:'cancel',reason})});if(!r.ok)throw new Error(await r.text());await loadPlatformCompanyDetail();await loadPlatformStats(false);notify('Opération annulée.','success');render()}catch(err){notify('Annulation impossible : '+(err?.message||err),'error',5000)}});

