 document.querySelectorAll('[data-baggage-preset]').forEach(b=>b.onclick=()=>{const today=new Date(),fmt=d=>d.toISOString().slice(0,10),preset=b.dataset.baggagePreset;let from=fmt(today),to=fmt(today);if(preset==='yesterday'){const d=new Date(today);d.setDate(d.getDate()-1);from=to=fmt(d)}else if(preset==='7days'){const d=new Date(today);d.setDate(d.getDate()-6);from=fmt(d)}else if(preset==='month'){from=fmt(new Date(today.getFullYear(),today.getMonth(),1))}state.baggageFilters={...(state.baggageFilters||{}),from,to};render()});
 const scanInto=id=>startQrScanner(raw=>{const el=document.querySelector(id);if(el){el.value=extractBaggageCode(raw)||String(raw||'').trim().toUpperCase();el.dispatchEvent(new Event('change',{bubbles:true}))}});
