 const pnr=document.querySelector('#baggagePnr'),ticketHint=document.querySelector('#baggageTicketHint');
 bindCameraInput('#takeBaggagePhoto','#baggagePhoto','#baggagePhotoStatus','#baggagePhotoPreview','bagage');
 const lookup=()=>{const raw=String(pnr?.value||'').trim().toUpperCase();if(!raw)return;const t=state.tickets.find(x=>String(x.pnr||'').toUpperCase()===raw);if(!t){if(ticketHint)ticketHint.textContent='Ticket non trouvé : la saisie manuelle reste autorisée.';return}const trip=state.ticketTrips.find(x=>x.id===t.tripId);const set=(id,v)=>{const el=document.querySelector(id);if(el&&v!==undefined&&v!==null)el.value=v};set('#baggagePassenger',t.passengerName);set('#baggagePhone',t.phone);set('#baggageDestination',t.dropPoint||t.destination);set('#baggageOrigin',t.boardingPoint||t.origin);set('#baggageTrip',t.tripId||'');if(ticketHint)ticketHint.textContent=`Ticket trouvé : ${t.passengerName} · ${trip?baggageTripLabel(trip):t.destination}`;notify('Informations du ticket récupérées.','success')};
 document.querySelector('#lookupBaggageTicket')?.addEventListener('click',lookup);pnr?.addEventListener('change',lookup);
 const phone=document.querySelector('#baggagePhone');phone?.addEventListener('change',()=>{const c=unifiedCustomerByPhone(phone.value);if(c){const n=document.querySelector('#baggagePassenger');if(n&&!n.value)n.value=c.name;notify(`Client retrouvé : ${c.name}`,'success')}});
 document.querySelector('#baggageTrip')?.addEventListener('change',e=>{const tr=state.ticketTrips.find(x=>x.id===e.target.value);if(tr){const o=document.querySelector('#baggageOrigin'),d=document.querySelector('#baggageDestination');if(o&&!o.value)o.value=tr.origin||'';if(d&&!d.value)d.value=tr.destination||''}});
 const f=document.querySelector('#baggageForm');if(f)f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('[type="submit"]');if(submit?.dataset.busy==='1')return;if(submit){submit.dataset.busy='1';submit.disabled=true}try{const d=Object.fromEntries(new FormData(f)),createdAt=now(),code=baggageCode(),photo=await readFileData(document.querySelector('#baggagePhoto')?.files?.[0]),paid=Number(d.paid||0),bag={...d,id:uid(),code,publicToken:uid(),baggageType:d.baggageType||'accompanied',phone:normalizePhone(d.phone),receiverPhone:normalizePhone(d.receiverPhone),count:Math.max(1,Number(d.count||1)),weight:Number(d.weight||0),paid,amount:paid,declaredValue:Number(d.declaredValue||0),agency:state.user.agency,status:d.tripId?'Affecté à un voyage':'Enregistré',createdAt,updatedAt:createdAt,createdBy:state.user.id,createdByName:state.user.name,photo,events:[{status:'Enregistré',at:createdAt,userId:state.user.id,agency:state.user.agency}]};if(d.pnr){const t=state.tickets.find(x=>String(x.pnr||'').toUpperCase()===String(d.pnr).trim().toUpperCase());if(t){bag.ticketId=t.id;bag.tripId=bag.tripId||t.tripId;bag.seat=t.seat||''}}state.ticketBaggage.push(bag);rememberCustomer(bag.phone,bag.passengerName);persist();audit('Bagage enregistré',code);resetOperationForm(f,`Bagage ${code} enregistré.`);render();setTimeout(()=>showBaggagePrintPrompt(bag),60)}finally{if(submit){submit.dataset.busy='0';submit.disabled=false}}};
 const tf=document.querySelector('#baggageTripForm');if(tf)tf.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(tf));state.ticketTrips.push({id:uid(),...d,status:'Planifié',source:'baggage',createdAt:now(),createdBy:state.user.id,createdByName:state.user.name});persist();resetOperationForm(tf,'Voyage créé. Il sera partagé avec Tickets.');render()};
 const sf=document.querySelector('#baggageScanForm');if(sf)sf.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(sf)),b=state.ticketBaggage.find(x=>String(x.code).toUpperCase()===String(d.code).trim().toUpperCase());if(!b)return notify('Bagage introuvable.','error');if(operationCancelled(b))return notify('Ce bagage est annulé.','warning');b.tripId=d.tripId;b.status='Chargé';b.loadedAt=now();b.updatedAt=now();b.events=[...(b.events||[]),{status:'Chargé',at:b.loadedAt,userId:state.user.id,agency:state.user.agency}];persist();audit('Bagage chargé',b.code);resetOperationForm(sf,`${b.code} marqué chargé.`);render()};
 const af=document.querySelector('#baggageArrivalForm');if(af)af.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(af)),b=state.ticketBaggage.find(x=>String(x.code).toUpperCase()===String(d.code).trim().toUpperCase());if(!b)return notify('Bagage introuvable.','error');if(operationCancelled(b))return notify('Ce bagage est annulé.','warning');b.status='Arrivé';b.arrivedAt=now();b.updatedAt=now();b.events=[...(b.events||[]),{status:'Arrivé',at:b.arrivedAt,userId:state.user.id,agency:state.user.agency}];persist();audit('Bagage arrivé',b.code);resetOperationForm(af,`${b.code} disponible au retrait.`);render()};
 const wf=document.querySelector('#baggageWithdrawalForm');if(wf)wf.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(wf)),a=String(d.receiptCode).trim().toUpperCase(),c=String(d.labelCode).trim().toUpperCase();if(a!==c)return notify('Le reçu client et l’étiquette ne correspondent pas.','error');const b=state.ticketBaggage.find(x=>String(x.code).toUpperCase()===a);if(!b)return notify('Bagage introuvable.','error');if(operationCancelled(b))return notify('Ce bagage est annulé.','warning');if(b.status==='Retiré')return notify('Ce bagage a déjà été retiré.','warning');if(!['Arrivé','Chargé','En transit'].includes(b.status))return notify(`Retrait impossible depuis le statut ${b.status}.`,'warning');b.status='Retiré';b.withdrawnAt=now();b.withdrawnBy=state.user.id;b.updatedAt=now();b.events=[...(b.events||[]),{status:'Retiré',at:b.withdrawnAt,userId:state.user.id,agency:state.user.agency}];persist();audit('Bagage retiré',b.code);resetOperationForm(wf,`Correspondance confirmée. ${b.code} remis au client.`);render()};
 document.querySelectorAll('[data-baggage-receipt]').forEach(x=>x.onclick=()=>{const b=state.ticketBaggage.find(v=>v.id===x.dataset.baggageReceipt);if(b)printBaggageReceiptNow(b)});document.querySelectorAll('[data-baggage-label]').forEach(x=>x.onclick=()=>{const b=state.ticketBaggage.find(v=>v.id===x.dataset.baggageLabel);if(b)printBaggageLabelNow(b)});document.querySelectorAll('[data-baggage-both]').forEach(x=>x.onclick=()=>{const b=state.ticketBaggage.find(v=>v.id===x.dataset.baggageBoth);if(b)printBaggageBothNow(b)});document.querySelectorAll('[data-baggage-photo]').forEach(x=>x.onclick=()=>showBaggagePhoto(state.ticketBaggage.find(v=>v.id===x.dataset.baggagePhoto)));
 document.querySelectorAll('[data-baggage-manifest]').forEach(x=>x.onclick=()=>{const tr=state.ticketTrips.find(t=>t.id===x.dataset.baggageManifest),h=document.querySelector('#ticketModal');if(!h)return;h.innerHTML=`<div class="modal-backdrop"><div class="modal wide-modal"><div class="modal-head"><div><h3>Manifeste Bagages</h3><p>${esc(baggageTripLabel(tr))}</p></div><button id="closeTicketModal">×</button></div>${baggageManifestHtml(tr)}</div></div>`;document.querySelector('#closeTicketModal').onclick=()=>h.innerHTML=''});
