function bindCameraInput(buttonSelector,inputSelector,statusSelector,previewSelector,label='colis'){
 const btn=document.querySelector(buttonSelector),input=document.querySelector(inputSelector),status=document.querySelector(statusSelector),preview=document.querySelector(previewSelector);if(!btn||!input)return;
 btn.onclick=async()=>{try{await ensureCameraPermission(false)}catch{}input.click()};
 input.onchange=async()=>{const file=input.files?.[0];if(!file){if(status)status.textContent='Aucune photo prise';if(preview)preview.innerHTML='';return}try{const data=await readFileData(file);input.dataset.dataUrl=data;if(status)status.textContent=`Photo du ${label} prête`;if(preview)preview.innerHTML=`<img src="${data}" alt="Aperçu photo ${esc(label)}">`;}catch(e){notify('Photo impossible : '+(e?.message||e),'error')}};
}
