 const testSelectedPrinter=async(kind)=>{const p=currentPrinter(),select=document.querySelector(kind==='receipt'?'#receiptPrinterSelect':'#labelPrinterSelect'),address=select?.value||(kind==='receipt'?(p.receiptPrinterAddress||p.bluetoothAddress):(p.labelPrinterAddress||p.bluetoothAddress));if(!address)return alert('Associez puis sélectionnez une imprimante Bluetooth.');try{await NativePrinter.printEscPosBluetooth({address,company:state.settings.companyName,receipt:kind==='receipt'?'TEST RECU CLIENT\nConnexion Bluetooth OK\nDate: '+new Date().toLocaleString('fr-FR'):'',parcel:kind==='parcel'?'YAM TRANS\nTEST TALON COLIS':'',receiptQr:'',parcelQr:'',printPart:kind==='receipt'?'receipt':'parcel',paperWidth:Number(document.querySelector('[name=printWidth]')?.value||p.printWidth||80)});alert(kind==='receipt'?'Test du reçu envoyé à l’imprimante sélectionnée.':'Test du talon envoyé à l’imprimante sélectionnée.');}catch(e){alert('Échec du test Bluetooth : '+(e?.message||e));}};
