function baggageTable(list){if(!list.length)return '<div class="empty">Aucun bagage enregistré.</div>';return `<div class="table-wrap"><table><thead><tr><th>Code</th><th>Type</th><th>Client</th><th>Trajet</th><th>Poids</th><th>Montant</th><th>Statut</th><th>Photo</th><th></th></tr></thead><tbody>${list.map(b=>`<tr class="${operationCancelled(b)?'cancelled-row':''}"><td><b>${esc(b.code)}</b><small>${new Date(b.createdAt).toLocaleString('fr-FR')}</small></td><td>${b.baggageType==='unaccompanied'?'Non accompagné':'Accompagné'}</td><td><b>${esc(b.passengerName||b.senderName||'')}</b><small>${esc(b.phone||'')}</small></td><td>${esc(b.origin||'')} → ${esc(b.destination||'')}</td><td>${Number(b.weight||0).toFixed(1)} kg</td><td>${operationCancelled(b)?'<span class="cancelled-amount">Annulé</span>':money(baggagePaidValue(b))}</td><td><span class="pill ${operationCancelled(b)?'warning':''}">${esc(operationCancelled(b)?'Annulé':b.status||'Enregistré')}</span></td><td>${b.photo?`<button data-baggage-photo="${b.id}">Aperçu</button>`:'—'}</td><td><button data-baggage-receipt="${b.id}">Imprimer reçu</button><button data-baggage-label="${b.id}">Imprimer étiquette</button><button class="primary" data-baggage-both="${b.id}">Les deux</button></td></tr>`).join('')}</tbody></table></div>`}
