 const pageSize=format==='A4'?'A4 portrait':format==='58'?'58mm 200mm':'80mm 220mm',summaryCols=cancelled>0?(thermal?'1fr':'repeat(3,1fr)'):(thermal?'1fr':'repeat(2,1fr)');
