async function ensureCameraPermission(showHelp=false){
  try{
    const status=await NativePrinter.cameraPermissionStatus();
    if(status?.state==='granted')return true;
    const result=await NativePrinter.requestCameraPermission();
    if(result?.granted)return true;
    if(showHelp){
      const open=confirm('La caméra est nécessaire pour scanner les QR codes et prendre les photos des colis. Ouvrir les paramètres de Yam-Trans pour l’autoriser ?');
      if(open)await NativePrinter.openAppSettings();
    }
    return false;
  }catch{
    try{
      const test=await navigator.mediaDevices.getUserMedia({video:true});
      test.getTracks().forEach(t=>t.stop());
      return true;
    }catch{return false}
  }
}

async function startQrScanner(onCode){
  const allowed=await ensureCameraPermission(true);
  if(!allowed){
    const code=prompt('La caméra n’est pas autorisée. Saisissez le code ou la référence :');
    if(code)onCode(code);
    return;
  }
  if(!('BarcodeDetector' in window)){
    const code=prompt('Le lecteur QR natif n’est pas disponible sur cet appareil. Saisissez le code ou la référence :');
    if(code)onCode(code);
    return;
  }
  let stream;
  const host=document.querySelector('#fullMenuHost')||document.body;
  host.innerHTML=`<div class="modal-backdrop"><div class="modal scanner-modal"><div class="modal-head"><div><span class="eyebrow">Scan sécurisé</span><h3>Scanner un QR code</h3></div><button id="closeScanner" aria-label="Fermer">×</button></div><div class="scanner-frame"><video id="qrVideo" autoplay playsinline></video><span class="scan-line"></span></div><p class="scanner-help">Placez le QR au centre du cadre. Colis, bagage, bordereau et manifeste sont reconnus automatiquement.</p><div class="modal-actions"><button id="scannerSettings">Autorisation caméra</button><button id="manualCode">Saisir le code</button></div></div></div>`;
  const close=()=>{stream?.getTracks().forEach(t=>t.stop());host.innerHTML=''};
  document.querySelector('#closeScanner').onclick=close;
  document.querySelector('#scannerSettings').onclick=async()=>{try{await NativePrinter.openAppSettings()}catch{}};
  document.querySelector('#manualCode').onclick=()=>{close();const code=prompt('Code ou référence :');if(code)onCode(code)};
  try{
    stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});
    const video=document.querySelector('#qrVideo');
    video.srcObject=stream;
    const detector=new BarcodeDetector({formats:['qr_code']});
    const loop=async()=>{
      if(!video.isConnected)return;
      try{
        const codes=await detector.detect(video);
        if(codes[0]){
          let value=codes[0].rawValue||'';
          value=extractShipmentCode(value);
          close();onCode(value);return;
        }
      }catch{}
      requestAnimationFrame(loop);
    };
    loop();
  }catch(e){
    close();
    const open=confirm('Impossible d’accéder à la caméra. Ouvrir les paramètres de Yam-Trans pour vérifier l’autorisation ?');
    if(open){try{await NativePrinter.openAppSettings()}catch{}}
    else{const code=prompt('Saisissez le code du colis :');if(code)onCode(code)}
  }
}


