function customerCenterPage(mode){
 const f=customerFilterState(mode),list=filteredCustomers(mode),label=mode==='courier'?'Courrier':mode==='baggage'?'Bagages':'Tickets',cities=uniqueSorted(unifiedCustomers().map(c=>c.city)),countries=uniqueSorted(unifiedCustomers().map(c=>c.country));
 return shell(`<section class="panel customer-center-head"><div class="panel-head responsive"><div><span class="eyebrow">CRM · ${label.toUpperCase()}</span><h2>Gestion des clients</h2><p>Identité commune, historique multi-services, fidélité, export et campagnes SMS.</p></div><div class="button-row"><button id="exportCustomers">${icon('excel')} Exporter</button><button id="smsSelectedCustomers">${icon('message')} SMS sélection</button><button id="newCustomer" class="primary">+ Nouveau client</button></div></div></section><section class="panel customer-filter-panel"><h3>Critères de recherche</h3><form id="customerFilterForm" data-customer-mode="${mode}" class="customer-filter-grid no-wizard"><fieldset><legend>Identification</legend><label>Nom / téléphone<input name="q" value="${esc(f.q||'')}" placeholder="Nom, prénom ou téléphone"></label></fieldset><fieldset><legend>Localisation</legend><label>Ville<select name="city"><option value="">Toutes</option>${cities.map(x=>`<option ${f.city===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label>Pays<select name="country"><option value="">Tous</option>${countries.map(x=>`<option ${f.country===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label></fieldset><fieldset><legend>Date d’inscription</legend><label>Depuis le<input type="date" name="from" value="${esc(f.from||'')}"></label><label>Jusqu’au<input type="date" name="to" value="${esc(f.to||'')}"></label></fieldset><fieldset><legend>Points de fidélité</legend><label>Min<input type="number" min="0" name="pointsMin" value="${esc(f.pointsMin||'')}"></label><label>Max<input type="number" min="0" name="pointsMax" value="${esc(f.pointsMax||'')}"></label></fieldset><fieldset><legend>Statut</legend><label>Statut<select name="status"><option value="">Tous les statuts</option><option ${f.status==='Actif'?'selected':''}>Actif</option><option ${f.status==='Prospect'?'selected':''}>Prospect</option><option ${f.status==='VIP'?'selected':''}>VIP</option><option ${f.status==='Inactif'?'selected':''}>Inactif</option></select></label><label>Actif<select name="active"><option value="">Tous</option><option value="yes" ${f.active==='yes'?'selected':''}>Oui</option><option value="no" ${f.active==='no'?'selected':''}>Non</option></select></label></fieldset><div class="customer-filter-actions"><button type="button" id="customerFilterReset">Réinitialiser</button><button class="primary">${icon('search')} Rechercher</button></div></form></section><section class="panel"><div class="panel-head responsive"><div><h3>${list.length} client(s)</h3><p>Sélectionnez plusieurs clients pour exporter ou envoyer une promotion SMS.</p></div><label class="select-all-clients"><input type="checkbox" id="selectAllCustomers"> Tout sélectionner</label></div>${customerCardsHtml(list,mode)}</section><div id="customerModal"></div>`)
}
function customerProfileHtml(c){
 const st=customerStats(c.phone),dest=[...st.destinations.entries()].sort((a,b)=>b[1].count-a[1].count),ag=[...st.agencies.entries()].sort((a,b)=>b[1]-a[1]),history=[...st.sent.map(x=>({at:x.createdAt,type:'Courrier',ref:x.code,label:`${x.origin} → ${x.destination}`,amount:shipmentFinancialAmount(x),status:operationCancelled(x)?'Annulé':x.status})),...st.bags.map(x=>({at:x.createdAt,type:'Bagage',ref:x.code,label:`${x.origin||''} → ${x.destination||''}`,amount:baggageFinancialAmount(x),status:operationCancelled(x)?'Annulé':x.status})),...st.tickets.map(x=>({at:x.createdAt,type:'Ticket',ref:x.pnr||x.code,label:`${x.origin||''} → ${x.destination||''}`,amount:['Annulé','Remboursé'].includes(x.status)?0:Number(x.paid||x.fare||0),status:x.status}))].sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,100);
 const monthMap=new Map();for(const x of history){if(!x.at)continue;const key=String(x.at).slice(0,7),v=monthMap.get(key)||{count:0,amount:0};v.count++;if(x.status!=='Annulé')v.amount+=Number(x.amount||0);monthMap.set(key,v)}const months=[...monthMap.entries()].sort((a,b)=>a[0].localeCompare(b[0])).slice(-8),maxCount=Math.max(1,...months.map(x=>x[1].count));
 return `<div class="customer-profile"><div class="customer-profile-hero"><div class="customer-avatar large">${esc(String(c.name||'?').split(/\s+/).slice(0,2).map(x=>x[0]||'').join('').toUpperCase())}</div><div><h2>${esc(c.name)}</h2><p>${esc(c.phone)} · ${esc(c.city||'Ville non renseignée')}${c.country?` · ${esc(c.country)}`:''}</p><small>Client depuis ${st.firstAt?new Date(st.firstAt).toLocaleDateString('fr-FR'):'—'} · Dernière opération ${st.lastAt?new Date(st.lastAt).toLocaleDateString('fr-FR'):'—'} · Statut ${esc(c.status||'Actif')}</small></div><span class="loyalty-badge ${loyaltyTierClass(st.points)}">${st.points} points · ${loyaltyTier(st.points)}</span></div><div class="customer-profile-kpis"><article><small>Total Courriers envoyés</small><b>${st.sent.length}</b></article><article><small>Bagages</small><b>${st.bags.length}</b></article><article><small>Billets</small><b>${st.tickets.length}</b></article><article><small>Montant total</small><b>${money(st.totalSpend)}</b></article><article><small>Montant moyen</small><b>${money(st.avg)}</b></article><article><small>Destinations différentes</small><b>${dest.length}</b></article></div><section class="customer-evolution"><h3>Évolution de l’activité</h3><p class="muted">Nombre d’opérations par mois, tous services confondus.</p><div class="customer-bar-chart">${months.map(([k,v])=>`<div class="customer-bar-item"><div class="customer-bar-value">${v.count}</div><div class="customer-bar-track"><i style="height:${Math.max(8,Math.round(v.count/maxCount*100))}%"></i></div><b>${esc(new Date(k+'-01T12:00').toLocaleDateString('fr-FR',{month:'short',year:'2-digit'}))}</b><small>${money(v.amount)}</small></div>`).join('')||'<div class="empty">Pas encore assez d’activité.</div>'}</div></section><div class="customer-profile-columns"><section><h3>Détail par destination</h3>${dest.map(([k,v])=>`<div class="profile-stat-line"><b>${esc(k)}</b><span>${v.count} opération(s)</span><span>${money(v.amount)}</span></div>`).join('')||'<p>Aucune destination.</p>'}</section><section><h3>Répartition par agence de dépôt</h3>${ag.map(([k,v])=>`<div class="profile-stat-line"><b>${esc(k)}</b><span>${v} courrier(s)</span></div>`).join('')||'<p>Aucune agence.</p>'}</section></div><section><h3>Historique des opérations</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Service</th><th>Référence</th><th>Trajet</th><th>Montant</th><th>Statut</th></tr></thead><tbody>${history.map(x=>`<tr><td>${x.at?new Date(x.at).toLocaleString('fr-FR'):'—'}</td><td>${esc(x.type)}</td><td><b>${esc(x.ref||'-')}</b></td><td>${esc(x.label)}</td><td>${x.status==='Annulé'?'<span class="cancelled-amount">Annulé</span>':money(x.amount)}</td><td>${esc(x.status||'-')}</td></tr>`).join('')||'<tr><td colspan="6">Aucune opération.</td></tr>'}</tbody></table></div></section></div>`
}
function openCustomerProfile(phone){
 const c=unifiedCustomers().find(x=>customerKey(x.phone)===customerKey(phone));if(!c)return notify('Client introuvable.','error');const h=document.querySelector('#customerModal')||document.querySelector('#ticketModal')||document.querySelector('#fullMenuHost');if(!h)return;
 h.innerHTML=`<div class="modal-backdrop"><div class="modal wide-modal customer-profile-modal"><div class="modal-head"><div><span class="eyebrow">FICHE CLIENT</span><h3>${esc(c.name)}</h3></div><button id="closeCustomerProfile">×</button></div>${customerProfileHtml(c)}<div class="modal-actions"><button id="editCustomerProfile">Modifier la fiche</button><button data-customer-operation="courier:${esc(c.phone)}">Nouvel envoi</button><button data-customer-operation="baggage:${esc(c.phone)}">Nouveau bagage</button><button data-customer-operation="tickets:${esc(c.phone)}">Nouveau billet</button><button id="customerSmsSingle" class="primary">Envoyer SMS</button></div></div></div>`;h.querySelector('#closeCustomerProfile').onclick=()=>h.innerHTML='';h.querySelectorAll('[data-customer-operation]').forEach(b=>b.onclick=()=>{h.innerHTML='';openCustomerOperation(b.dataset.customerOperation)});h.querySelector('#customerSmsSingle').onclick=()=>openCustomerSmsComposer([c]);h.querySelector('#editCustomerProfile').onclick=()=>openEditCustomerModal(c.phone)
}
function openCustomerOperation(value){const [service,raw]=String(value||'').split(':',2),phone=customerKey(raw),c=unifiedCustomers().find(x=>customerKey(x.phone)===phone);if(!c)return;state.customerPrefill={service,phone:c.phone,name:c.name};navigatePage(service==='baggage'?'baggageNew':service==='tickets'?'ticketSale':'new')}
function saveCustomerProfile(data,existingPhone=''){
 const phone=customerKey(data.phone),oldPhone=customerKey(existingPhone||phone);if(!phone||!data.name)throw new Error('Nom et téléphone sont obligatoires.');
 if(existingPhone&&oldPhone&&oldPhone!==phone){
  for(const s of state.shipments){if(customerKey(s.senderPhone)===oldPhone)s.senderPhone=phone;if(customerKey(s.receiverPhone)===oldPhone)s.receiverPhone=phone}
  for(const t of state.tickets){if(customerKey(t.phone)===oldPhone)t.phone=phone}
  for(const b of state.ticketBaggage){if(customerKey(b.phone)===oldPhone)b.phone=phone;if(customerKey(b.receiverPhone)===oldPhone)b.receiverPhone=phone}
  for(const x of state.loyaltyTransactions){if(customerKey(x.phone)===oldPhone)x.phone=phone}
  for(const c of state.ticketCustomers){if(customerKey(c.phone)===oldPhone)c.phone=phone}
 }
 let i=state.customers.findIndex(c=>customerKey(c.phone)===oldPhone),record={...(i>=0?state.customers[i]:{}),id:i>=0?(state.customers[i].id||uid()):uid(),phone,name:String(data.name).trim(),city:String(data.city||'').trim(),country:String(data.country||'').trim(),status:data.status||'Actif',active:data.active!=='false',notes:String(data.notes||'').trim(),loyaltyActiveSince:data.loyaltyActiveSince||'',createdAt:(i>=0?state.customers[i].createdAt:'')||now(),updatedAt:now()};if(i>=0)state.customers[i]=record;else state.customers.push(record);persist();return record
}
function openEditCustomerModal(phone){const c=unifiedCustomers().find(x=>customerKey(x.phone)===customerKey(phone));if(!c)return;const meta=customerMeta(phone),h=document.querySelector('#customerModal')||document.querySelector('#ticketModal')||document.querySelector('#fullMenuHost');if(!h)return;h.innerHTML=`<div class="modal-backdrop"><form id="customerEditForm" class="modal"><div class="modal-head"><div><span class="eyebrow">MODIFIER CLIENT</span><h3>${esc(c.name)}</h3></div><button type="button" id="closeCustomerEdit">×</button></div><div class="grid"><label>Nom / prénom<input name="name" value="${esc(c.name)}" required></label><label>Téléphone<input name="phone" value="${esc(c.phone)}" inputmode="tel" required></label><label>Ville<input name="city" value="${esc(c.city||'')}"></label><label>Pays<input name="country" value="${esc(c.country||'')}"></label><label>Statut<select name="status">${['Actif','Prospect','VIP','Inactif'].map(x=>`<option ${String(c.status||'Actif')===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Fidélité active depuis<input type="date" name="loyaltyActiveSince" value="${esc(meta.loyaltyActiveSince||'')}"></label></div><label>Notes<textarea name="notes">${esc(meta.notes||'')}</textarea></label><button class="primary">Enregistrer les modifications</button></form></div>`;h.querySelector('#closeCustomerEdit').onclick=()=>h.innerHTML='';h.querySelector('#customerEditForm').onsubmit=e=>{e.preventDefault();try{const saved=saveCustomerProfile(Object.fromEntries(new FormData(e.target)),c.phone);h.innerHTML='';notify('Fiche client mise à jour.','success');render();setTimeout(()=>openCustomerProfile(saved.phone),50)}catch(err){notify(err.message||String(err),'error')}}}
function openNewCustomerModal(){const h=document.querySelector('#customerModal')||document.querySelector('#fullMenuHost');if(!h)return;h.innerHTML=`<div class="modal-backdrop"><form id="customerCreateForm" class="modal"><div class="modal-head"><div><span class="eyebrow">NOUVEAU CLIENT</span><h3>Créer une fiche client</h3></div><button type="button" id="closeCustomerCreate">×</button></div><div class="grid"><label>Nom / prénom<input name="name" required></label><label>Téléphone<input name="phone" inputmode="tel" required></label><label>Ville<input name="city"></label><label>Pays<input name="country"></label><label>Statut<select name="status"><option>Actif</option><option>Prospect</option><option>VIP</option><option>Inactif</option></select></label><label>Fidélité active depuis<input type="date" name="loyaltyActiveSince"></label></div><label>Notes<textarea name="notes"></textarea></label><button class="primary">Enregistrer</button></form></div>`;h.querySelector('#closeCustomerCreate').onclick=()=>h.innerHTML='';h.querySelector('#customerCreateForm').onsubmit=e=>{e.preventDefault();try{saveCustomerProfile(Object.fromEntries(new FormData(e.target)));h.innerHTML='';notify('Client enregistré.','success');render()}catch(err){notify(err.message||String(err),'error')}}}
async function exportCustomerList(mode){const list=filteredCustomers(mode),rows=[['Nom','Téléphone','Ville','Pays','Statut','Services','Client depuis','Dernière opération','Courriers','Bagages','Billets','Montant total','Points','Niveau'],...list.map(c=>{const st=customerStats(c.phone);return [c.name,c.phone,c.city||'',c.country||'',c.status||'Actif',c.sources.join(' + '),st.firstAt||'',st.lastAt||'',st.sent.length,st.bags.length,st.tickets.length,st.totalSpend,st.points,loyaltyTier(st.points)]})],csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\r\n');await saveOrShareBlob(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),`clients-${mode}-${new Date().toISOString().slice(0,10)}.csv`);audit('Export clients',`${mode} · ${list.length} clients`)}
function selectedCustomers(mode){const set=state.customerSelection[mode]||new Set();return unifiedCustomers().filter(c=>set.has(c.phone))}
function openCustomerSmsComposer(list){if(!list?.length)return notify('Sélectionnez au moins un client.','warning');if(!companyFeatures().sms&&!state.settings.smsEnabled)return notify('Le canal SMS n’est pas activé pour cette société.','warning',5000);const h=document.querySelector('#customerModal')||document.querySelector('#ticketModal')||document.querySelector('#fullMenuHost');if(!h)return;h.innerHTML=`<div class="modal-backdrop"><form id="customerSmsForm" class="modal"><div class="modal-head"><div><span class="eyebrow">CAMPAGNE SMS</span><h3>${list.length} destinataire(s)</h3></div><button type="button" id="closeCustomerSms">×</button></div><p>Le SMS sera envoyé uniquement aux clients sélectionnés via le canal SMS configuré pour la société.</p><textarea name="message" rows="6" maxlength="480" required placeholder="Ex. Promotion YAM TRANS : -10% sur vos envois cette semaine."></textarea><div class="security-note">${esc(list.slice(0,5).map(c=>c.name).join(', '))}${list.length>5?'…':''}</div><button class="primary">Envoyer les SMS</button></form></div>`;h.querySelector('#closeCustomerSms').onclick=()=>h.innerHTML='';h.querySelector('#customerSmsForm').onsubmit=async e=>{e.preventDefault();const btn=e.target.querySelector('button.primary'),msg=new FormData(e.target).get('message');setButtonBusy(btn,true,'Envoi…');let ok=0,fail=0;for(const c of list){try{if(await sendChannel('sms',c.phone,String(msg),'promotion','clients'))ok++;else fail++}catch{fail++}}setButtonBusy(btn,false);h.innerHTML='';notify(`${ok} SMS envoyé(s)${fail?` · ${fail} échec(s)`:''}.`,fail?'warning':'success',5000);audit('Campagne SMS clients',`${ok} envoyé(s), ${fail} échec(s)`)}}
async function sendChannel(channel,to,message,kind='generic',reference='',ticketUrl=''){if(!navigator.onLine||!state.authToken){notify('Connexion Internet requise pour envoyer le message.','warning');return false}try{const r=await fetch(SERVER_URL()+'/api/v2/notifications/send',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+state.authToken},body:JSON.stringify({channel,to:normalizePhone(to),message,kind,reference,ticketUrl})});if(!r.ok)throw new Error(await r.text());return true}catch(e){console.warn(e);return false}}

function loyaltyCustomers(program){const mode=program==='courier'?'courier':'tickets',f=state.loyaltyFilters[program]||{q:'',tier:'',min:''};state.loyaltyFilters[program]=f;return unifiedCustomers().filter(c=>customerSourcesForMode(mode,c)).filter(c=>{const st=customerStats(c.phone),points=program==='courier'?st.courierPoints:st.ticketPoints,q=String(f.q||'').toLowerCase();return(!q||`${c.name} ${c.phone}`.toLowerCase().includes(q))&&(!f.tier||loyaltyTier(points)===f.tier)&&(f.min===''||points>=Number(f.min))}).map(c=>({c,st:customerStats(c.phone),points:program==='courier'?customerStats(c.phone).courierPoints:customerStats(c.phone).ticketPoints}))}
function loyaltyCenterPage(program){const courier=program==='courier',rows=loyaltyCustomers(program),f=state.loyaltyFilters[program]||{},totalPoints=rows.reduce((a,x)=>a+x.points,0),active=rows.filter(x=>x.points>0).length;return shell(`<section class="panel loyalty-hero"><div><span class="eyebrow">FIDÉLITÉ ${courier?'COURRIER':'TICKETS'}</span><h2>Portefeuille et connaissance client</h2><p>Points, niveau, activité, dépenses et historique sont reliés à la fiche client commune.</p></div><div class="loyalty-hero-stats"><b>${rows.length}</b><span>clients</span><b>${totalPoints}</b><span>points nets</span><b>${active}</b><span>clients actifs</span></div></section><div class="admin-grid loyalty-layout"><section class="panel"><h3>Paramètres du programme</h3>${courier?`<form id="courierLoyaltyForm" class="settings-form"><label>Mode<select name="loyaltyMode"><option value="separate" ${state.settings.loyaltyMode!=='shared'?'selected':''}>Séparé Courrier / Tickets</option><option value="shared" ${state.settings.loyaltyMode==='shared'?'selected':''}>Portefeuille commun</option></select></label><label>Points par 1 000 FCFA<input type="number" step="0.1" min="0" name="courierLoyaltyPointsPer1000" value="${state.settings.courierLoyaltyPointsPer1000||1}"></label><label>Valeur d’un point (FCFA)<input type="number" min="0" name="courierLoyaltyRedeemValue" value="${state.settings.courierLoyaltyRedeemValue||10}"></label><button class="primary">Enregistrer</button></form>`:`<form id="loyaltySettingsForm" class="settings-form"><label>Points gagnés par 1 000 FCFA<input type="number" name="loyaltyPointsPer1000" min="0" step="0.1" value="${state.settings.loyaltyPointsPer1000||1}"></label><label>Valeur de 1 point (FCFA)<input type="number" name="loyaltyRedeemValue" min="0" value="${state.settings.loyaltyRedeemValue||10}"></label><label>Bonus nouveau client<input type="number" name="loyaltyWelcomePoints" min="0" value="${state.settings.loyaltyWelcomePoints||0}"></label><button class="primary">Enregistrer</button></form>`}<div class="loyalty-levels"><span class="bronze">Bronze · 0+</span><span class="argent">Argent · 100+</span><span class="or">Or · 300+</span><span class="platine">Platine · 700+</span></div></section><section class="panel"><div class="panel-head"><div><h3>Clients fidélité</h3><p>Filtrez puis ouvrez une fiche pour voir son historique complet.</p></div></div><form id="loyaltyFilterForm" data-program="${program}" class="loyalty-filter no-wizard"><input name="q" value="${esc(f.q||'')}" placeholder="Nom ou téléphone"><select name="tier"><option value="">Tous les niveaux</option>${['Bronze','Argent','Or','Platine'].map(x=>`<option ${f.tier===x?'selected':''}>${x}</option>`).join('')}</select><input type="number" name="min" min="0" value="${esc(f.min||'')}" placeholder="Points minimum"><button class="primary">Filtrer</button></form><div class="loyalty-customer-list">${rows.map(({c,st,points})=>`<button type="button" data-customer-profile="${esc(c.phone)}" class="loyalty-customer-row"><span class="customer-avatar">${esc(String(c.name).split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase())}</span><span><b>${esc(c.name)}</b><small>${esc(c.phone)} · ${st.totalOps} opération(s) · ${money(st.totalSpend)}</small></span><span class="loyalty-badge ${loyaltyTierClass(points)}">${points} pts · ${loyaltyTier(points)}</span></button>`).join('')||'<div class="empty">Aucun client selon ces critères.</div>'}</div></section></div><div id="customerModal"></div>`)}

function manifestQrPayload(m){return JSON.stringify({v:2,type:'courier_manifest',company:state.company?.code||'',id:m.id,code:m.code})}
function baggageManifestCode(trip){if(trip?.baggageManifestCode)return trip.baggageManifestCode;const d=String(trip?.departureAt||trip?.createdAt||ticketToday()).slice(0,10).replaceAll('-',''),seed=String(trip?.id||uid()).replace(/[^a-z0-9]/gi,'').toUpperCase().slice(-6)||Math.random().toString(36).slice(2,8).toUpperCase();return `MBG-${d}-${seed}`}
function baggageManifestQrPayload(trip){return JSON.stringify({v:2,type:'baggage_manifest',company:state.company?.code||'',tripId:trip.id,code:baggageManifestCode(trip)})}
function confirmCourierManifestDeparture(m){if(!m)return false;if(m.dispatchedAt)return notify('Le départ de ce bordereau est déjà confirmé.','warning');if(!confirm(`Confirmer le départ du bordereau ${m.code} ?`))return false;const at=now();m.dispatchedAt=at;m.updatedAt=at;for(const sh of manifestRows(m)){if(operationCancelled(sh))continue;if(['Enregistré','En attente de départ'].includes(sh.status)){sh.status='Expédié';sh.updatedAt=at;sh.events=sh.events||[];sh.events.push({id:uid(),status:'Expédié',at,userId:state.user.id,agency:sh.origin,note:`Départ confirmé - ${m.code}`})}}persist();audit('Départ bordereau confirmé',m.code);notify(`Départ ${m.code} confirmé.`,'success');render();return true}
function confirmCourierManifestArrival(m){if(!m)return false;if(!m.dispatchedAt)return notify('Confirmez d’abord le départ du bordereau.','warning');if(m.arrivedAt)return notify('L’arrivée de ce bordereau est déjà confirmée.','warning');if(!confirm(`Confirmer l’arrivée du bordereau ${m.code} ? Tous les colis seront marqués arrivés.`))return false;const at=now();m.arrivedAt=at;m.arrivedBy=state.user.id;m.updatedAt=at;let changed=0;for(const sh of manifestRows(m)){if(operationCancelled(sh)||sh.status==='Livré')continue;if(!['Arrivé à destination','Disponible pour retrait'].includes(sh.status)){sh.status='Arrivé à destination';sh.receivedAt=sh.receivedAt||at;sh.updatedAt=at;sh.events=sh.events||[];sh.events.push({id:uid(),status:'Arrivé à destination',at,userId:state.user.id,agency:sh.destination,note:`Arrivée bordereau confirmée - ${m.code}`});changed++}}persist();audit('Arrivée bordereau confirmée',`${m.code} · ${changed} colis`);notify(`${changed} colis marqué(s) arrivés.`,'success');render();return true}
async function openCourierManifestByScan(raw){const code=extractShipmentCode(raw),m=state.manifests.find(x=>String(x.code).toUpperCase()===String(code).toUpperCase()||String(x.id)===String(code));if(!m)return notify('Bordereau introuvable.','error');await previewManifest(m)}
async function openBaggageManifest(trip){if(!trip)return;const h=document.querySelector('#ticketModal')||document.querySelector('#fullMenuHost');if(!h)return;const qr=await QRCode.toDataURL(baggageManifestQrPayload(trip),{margin:1,width:260});h.innerHTML=`<div class="modal-backdrop"><div class="modal wide-modal"><div class="modal-head"><div><span class="eyebrow">${esc(baggageManifestCode(trip))}</span><h3>Manifeste Bagages</h3><p>${esc(baggageTripLabel(trip))}</p></div><button id="closeTicketModal">×</button></div>${baggageManifestHtml(trip,qr)}<div class="modal-actions"><button id="printBaggageManifestModal">${icon('print')} Imprimer manifeste</button>${trip.baggageManifestArrivedAt?'':`<button id="arriveBaggageManifestModal" class="primary">Confirmer arrivée</button>`}</div></div></div>`;h.querySelector('#closeTicketModal').onclick=()=>h.innerHTML='';h.querySelector('#printBaggageManifestModal').onclick=()=>printBaggageManifest(trip.id);h.querySelector('#arriveBaggageManifestModal')?.addEventListener('click',()=>confirmBaggageManifestArrival(trip.id));h.querySelectorAll('[data-manifest-baggage-withdraw]').forEach(b=>b.onclick=()=>{const bag=state.ticketBaggage.find(x=>x.id===b.dataset.manifestBaggageWithdraw);h.innerHTML='';state.prefillBaggageWithdrawalCode=bag?.code||'';navigatePage('baggageWithdrawal')})}
async function openBaggageManifestByScan(raw){const code=extractShipmentCode(raw),trip=state.ticketTrips.find(t=>String(baggageManifestCode(t)).toUpperCase()===String(code).toUpperCase()||String(t.id)===String(code));if(!trip)return notify('Manifeste bagages introuvable.','error');await openBaggageManifest(trip)}

function applyCustomerPrefill(){const p=state.customerPrefill;if(!p)return;if(p.service==='courier'&&state.page==='new'){const phone=document.querySelector('#senderPhone'),name=document.querySelector('#senderName');if(phone)phone.value=p.phone;if(name)name.value=p.name;state.customerPrefill=null;notify(`Client sélectionné : ${p.name}`,'success')}else if(p.service==='baggage'&&state.page==='baggageNew'){const phone=document.querySelector('#baggagePhone'),name=document.querySelector('#baggagePassenger');if(phone)phone.value=p.phone;if(name)name.value=p.name;state.customerPrefill=null;notify(`Client sélectionné : ${p.name}`,'success')}else if(p.service==='tickets'&&state.page==='ticketSale'){const phone=document.querySelector('#ticketCustomerPhone'),name=document.querySelector('#ticketPassengerName');if(phone)phone.value=p.phone;if(name)name.value=p.name;state.customerPrefill=null;notify(`Client sélectionné : ${p.name}`,'success')}}
function bindV46Features(){
 applyCustomerPrefill();
 if(state.page==='baggageWithdrawal'&&state.prefillBaggageWithdrawalCode){const e=document.querySelector('#baggageReceiptCode');if(e)e.value=state.prefillBaggageWithdrawalCode;state.prefillBaggageWithdrawalCode=''}
 const mode=document.querySelector('#customerFilterForm')?.dataset.customerMode;
 const cf=document.querySelector('#customerFilterForm');if(cf)cf.onsubmit=e=>{e.preventDefault();state.customerFilters[mode]=Object.fromEntries(new FormData(cf));render()};document.querySelector('#customerFilterReset')?.addEventListener('click',()=>{state.customerFilters[mode]={q:'',from:'',to:'',city:'',country:'',pointsMin:'',pointsMax:'',status:'',active:''};render()});
 document.querySelector('#newCustomer')?.addEventListener('click',openNewCustomerModal);document.querySelector('#exportCustomers')?.addEventListener('click',e=>withBusyButton(e.currentTarget,()=>exportCustomerList(mode),'Préparation export…'));
 document.querySelectorAll('[data-customer-profile]').forEach(b=>b.onclick=e=>{e.preventDefault();openCustomerProfile(b.dataset.customerProfile)});document.querySelectorAll('[data-customer-operation]').forEach(b=>b.onclick=()=>openCustomerOperation(b.dataset.customerOperation));
 if(mode){state.customerSelection[mode]=state.customerSelection[mode]||new Set();document.querySelectorAll('[data-customer-select]').forEach(x=>x.onchange=()=>{const set=state.customerSelection[mode];x.checked?set.add(x.dataset.customerSelect):set.delete(x.dataset.customerSelect)});const all=document.querySelector('#selectAllCustomers');if(all)all.onchange=()=>{const set=state.customerSelection[mode];for(const c of filteredCustomers(mode)){all.checked?set.add(c.phone):set.delete(c.phone)}render()};document.querySelector('#smsSelectedCustomers')?.addEventListener('click',()=>openCustomerSmsComposer(selectedCustomers(mode)))}
 document.querySelector('#loyaltyFilterForm')?.addEventListener('submit',e=>{e.preventDefault();const program=e.target.dataset.program;state.loyaltyFilters[program]=Object.fromEntries(new FormData(e.target));render()});
 document.querySelector('#scanCourierManifest')?.addEventListener('click',()=>startQrScanner(openCourierManifestByScan));document.querySelector('#scanBaggageManifest')?.addEventListener('click',()=>startQrScanner(openBaggageManifestByScan));
 document.querySelectorAll('[data-arrive-manifest]').forEach(b=>b.onclick=()=>confirmCourierManifestArrival(state.manifests.find(m=>m.id===b.dataset.arriveManifest)));document.querySelectorAll('[data-dispatch-manifest]').forEach(b=>b.onclick=()=>confirmCourierManifestDeparture(state.manifests.find(m=>m.id===b.dataset.dispatchManifest)));
 document.querySelectorAll('[data-baggage-manifest]').forEach(b=>b.onclick=()=>openBaggageManifest(state.ticketTrips.find(t=>t.id===b.dataset.baggageManifest)));
}

window.__yamHandleNativeBack=()=>{
 try{
  const modal=document.querySelector('.modal-backdrop');if(modal){const close=modal.querySelector('#closeFullMenu,#closeTicketModal,#closeCustomerProfile,#closeCustomerCreate,#closeCustomerSms,#closeManifestPreview,#closeManifest,#closeWithdraw,#closeScanner,#modalClose,#closeModal,button[aria-label="Fermer"]');if(close&&typeof close.click==='function')close.click();else modal.remove();return true}
  if(!state.user)return false;
  state.navigationStack=Array.isArray(state.navigationStack)?state.navigationStack:[];
  const prev=state.navigationStack.pop();if(prev&&prev!==state.page){navigatePage(prev,{replace:true,fromBack:true});return true}
  const root=state.activeModule==='tickets'?'ticketDashboard':state.activeModule==='baggage'?'baggageDashboard':'dashboard';if(state.page!==root){navigatePage(root,{replace:true,fromBack:true});return true}
  if(state.page!=='modules'){navigatePage('modules',{replace:true,fromBack:true});return true}
  return false
 }catch(e){console.warn('Back navigation',e);return false}
};

cleanupOldPhotos();
const initialWebPage=pageFromLocation();if(initialWebPage&&state.user)state.page=initialWebPage;
pingServer().then(async()=>{if(state.user&&state.authToken){if(isPlatformAdmin()){state.page='admin';await loadPlatformStats(false);render()}else syncNow(true).finally(render)}});
setInterval(()=>{const today=ticketToday();if(state.dashboardAutoDate&&state.dashboardDate!==today){state.dashboardDate=today;if(state.user&&['dashboard','ticketDashboard'].includes(state.page))render()}pingServer().then(ok=>{if(ok&&state.user&&state.authToken&&!isPlatformAdmin())syncNow(true);else if(state.user&&!isPlatformAdmin())render()})},60000);
render();
